// <auto-generated-scaffold>
//   HAND-WRITTEN. Mechanism A: the warehouse calls us.
// </auto-generated-scaffold>
#nullable enable

using Wolverine;
using Wolverine.Http;
using StockFeed.Contracts;   // StockNoticed — the model-declared foreign event

namespace StockFeed.Landing;

/// <summary>
/// MECHANISM A: an HTTP endpoint the warehouse posts to. The cheapest thing that works, and what most
/// integrations actually are.
///
/// Its body is the WAREHOUSE'S schema, which is the point: this method and
/// <see cref="StockNoticed"/> are the only two places in the system that speak it.
///
/// WHAT IT CANNOT DO IS FORGET. If the warehouse's POST fails — our host down, a network partition, a 500 —
/// the notice exists nowhere on our side and there is nothing to re-read. Recovery is entirely the caller's
/// retry policy, i.e. entirely outside our control and unknowable from here. For a black box documented as
/// notifying us "whenever a change occurs" and never re-sending, that is the argument against this mechanism
/// however convenient it is. It is also why the response below distinguishes stored from duplicate rather
/// than answering 200 to everything: a caller that cannot tell the difference cannot retry safely.
///
/// AND NOTE WHAT IS ASYMMETRIC ABOUT IT. A listener and a clock are absent unless configuration switches
/// them on. A route is not: Wolverine.HTTP discovers this method whatever <c>Feed:Landing</c> says, so the
/// only way to "not choose" a webhook is for the webhook to refuse. Worth knowing beyond this reference —
/// an unchosen webhook is still public surface, and a comparison that let the route answer anyway would be
/// measuring nothing.
/// </summary>
public static class WarehouseWebhookEndpoint
{
    [WolverinePost("/feed/stock-notices")]
    public static async Task<IResult> Post(StockNoticed notice, IMessageBus bus)
    {
        if (StockFeedLanding.Chosen != StockFeedLanding.Mechanism.Webhook)
            return Results.StatusCode(StatusCodes.Status503ServiceUnavailable);

        // InvokeAsync, not PublishAsync, so the translation runs INSIDE this request. That matters for the one
        // thing the caller genuinely needs to know: whether to retry. A failure surfaces as a 500 and they
        // should; anything else means we have it.
        await bus.InvokeAsync(notice);

        // 202, and nothing about the outcome. A redelivery, a stale notice and a fresh translation are all
        // "accepted" from the warehouse's point of view — what we decided to do with it is our business, and
        // reporting AlreadyApplied as a 4xx would make a correct client under at-least-once look broken and
        // invite somebody to switch its retries off.
        //
        // The first version answered 200 with a stored/duplicate body. That leaked our decision to a system that
        // cannot act on it, and it only existed because ingest was a separate step with its own outcome type.
        return Results.Accepted();
    }
}
